-- ============================================================================
-- 0029_mundane_equipment_tokens_part1of2.sql
--
-- SRD 5.1 mundane equipment (237 items, CC-BY-4.0) as common 'item' tokens:
-- weapons, armor, adventuring gear, tools, poisons, ammo, trade goods, vehicles.
-- Reuses the violet Items monogram placeholders. Run both parts, any order.
-- Idempotent: skips an item you already have by name. Attribution: SRD 5.1.
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, details)
  select me, v.name, v.image_url, 'item', 'medium',
         jsonb_build_object('kind','item','item', v.item::jsonb)
  from (values
    ('Abacus', '/icons/items/_mono/A.svg', '{"name":"Abacus","itemType":"Adventuring Gear","rarity":"common","description":"An abacus.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":2}'),
    ('Acid', '/icons/items/_mono/A.svg', '{"name":"Acid","itemType":"Adventuring Gear","rarity":"common","description":"As an action, you can splash the contents of this vial onto a creature within 5 feet of you or throw the vial up to 20 feet, shattering it on impact. In either case, make a ranged attack against a creature or object, treating the acid as an improvised weapon. On a hit, the target takes 2d6 acid damage.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Acid (vial)', '/icons/items/_mono/A.svg', '{"name":"Acid (vial)","itemType":"Adventuring Gear","rarity":"common","description":"As an action, you can splash the contents of this vial onto a creature within 5 feet of you or throw the vial up to 20 feet, shattering it on impact. In either case, make a ranged attack against a creature or object, treating the acid as an improvised weapon. On a hit, the target takes 2d6 acid damage.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":1}'),
    ('Alchemist''s Fire (Flask)', '/icons/items/_mono/A.svg', '{"name":"Alchemist''s Fire (Flask)","itemType":"Adventuring Gear","rarity":"common","description":"This sticky, adhesive fluid ignites when exposed to air. As an action, you can throw this flask up to 20 feet, shattering it on impact. Make a ranged attack against a creature or object, treating the alchemist''s fire as an improvised weapon. On a hit, the target takes 1d4 fire damage at the start of each of its turns. A creature can end this damage by using its action to make a DC 10 Dexterity check to extinguish the flames.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":1}'),
    ('Alchemist''s Supplies', '/icons/items/_mono/A.svg', '{"name":"Alchemist''s Supplies","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":8}'),
    ('Amulet', '/icons/items/_mono/A.svg', '{"name":"Amulet","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as a holy symbol.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":1}'),
    ('Antitoxin (Vial)', '/icons/items/_mono/A.svg', '{"name":"Antitoxin (Vial)","itemType":"Adventuring Gear","rarity":"common","description":"A creature that drinks this vial of liquid gains advantage on saving throws against poison for 1 hour. It confers no benefit to undead or constructs.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp"}'),
    ('Arrow (bow)', '/icons/items/_mono/A.svg', '{"name":"Arrow (bow)","itemType":"Ammunition","rarity":"common","description":"An arrow for a bow.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":0.05}'),
    ('Assassin''s Blood', '/icons/items/_mono/A.svg', '{"name":"Assassin''s Blood","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must make a DC 10 Constitution saving throw. On a failed save, it takes 6 (1d12) poison damage and is poisoned for 24 hours. On a successful save, the creature takes half damage and isn''t poisoned.\\n\\n\r\n\r\n**_Ingested._** A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing advantage on the saving throw or dealing only half damage on a failed save.","source":"SRD 5.1, CC-BY-4.0","cost":"150 gp"}'),
    ('Backpack', '/icons/items/_mono/B.svg', '{"name":"Backpack","itemType":"Adventuring Gear","rarity":"common","description":"A backpack. Capacity: 1 cubic foot/30 pounds of gear.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":5}'),
    ('Bagpipes', '/icons/items/_mono/B.svg', '{"name":"Bagpipes","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":6}'),
    ('Ball Bearings (bag of 1000)', '/icons/items/_mono/B.svg', '{"name":"Ball Bearings (bag of 1000)","itemType":"Adventuring Gear","rarity":"common","description":"As an action, you can spill these tiny metal balls from their pouch to cover a level, square area that is 10 feet on a side. A creature moving across the covered area must succeed on a DC 10 Dexterity saving throw or fall prone. A creature moving through the area at half speed doesn''t need to make the save.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":2}'),
    ('Barrel', '/icons/items/_mono/B.svg', '{"name":"Barrel","itemType":"Adventuring Gear","rarity":"common","description":"A barrel. Capacity: 40 gallons liquid, 4 cubic feet solid.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":70}'),
    ('Basket', '/icons/items/_mono/B.svg', '{"name":"Basket","itemType":"Adventuring Gear","rarity":"common","description":"A basket. Capacity: 2 cubic feet/40 pounds of gear.","source":"SRD 5.1, CC-BY-4.0","cost":"4 sp","weight":2}'),
    ('Battleaxe', '/icons/items/_mono/B.svg', '{"name":"Battleaxe","itemType":"Weapon","rarity":"common","description":"A battleaxe.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":4,"damage":"1d8","damageType":"slashing","properties":["Versatile (1d10)"]}'),
    ('Bedroll', '/icons/items/_mono/B.svg', '{"name":"Bedroll","itemType":"Adventuring Gear","rarity":"common","description":"A bedroll.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":7}'),
    ('Bell', '/icons/items/_mono/B.svg', '{"name":"Bell","itemType":"Adventuring Gear","rarity":"common","description":"A bell.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp"}'),
    ('Blanket', '/icons/items/_mono/B.svg', '{"name":"Blanket","itemType":"Adventuring Gear","rarity":"common","description":"A blanket.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp"}'),
    ('Block and Tackle', '/icons/items/_mono/B.svg', '{"name":"Block and Tackle","itemType":"Adventuring Gear","rarity":"common","description":"A set of pulleys with a cable threaded through them and a hook to attach to objects, a block and tackle allows you to hoist up to four times the weight you can normally lift.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":5}'),
    ('Blowgun', '/icons/items/_mono/B.svg', '{"name":"Blowgun","itemType":"Weapon","rarity":"common","description":"A blowgun.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":1,"damage":"1","damageType":"piercing","properties":["Ammunition (range 25/100)","Loading"]}'),
    ('Blowgun needles', '/icons/items/_mono/B.svg', '{"name":"Blowgun needles","itemType":"Ammunition","rarity":"common","description":"Needles to be fired with a blowgun.","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp","weight":0.02}'),
    ('Book', '/icons/items/_mono/B.svg', '{"name":"Book","itemType":"Adventuring Gear","rarity":"common","description":"A book might contain poetry, historical accounts, information pertaining to a particular field of lore, diagrams and notes on gnomish contraptions, or just about anything else that can be represented using text or pictures. A book of spells is a spellbook (described later in this section).","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":5}'),
    ('Bottle, glass', '/icons/items/_mono/B.svg', '{"name":"Bottle, glass","itemType":"Adventuring Gear","rarity":"common","description":"A glass bottle. Capacity: 1.5 pints liquid.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":2}'),
    ('Breastplate', '/icons/items/_mono/B.svg', '{"name":"Breastplate","itemType":"Armor","rarity":"common","description":"This armor consists of a fitted metal chest piece worn with supple leather. Although it leaves the legs and arms relatively unprotected, this armor provides good protection for the wearer''s vital organs while leaving the wearer relatively unencumbered.","source":"SRD 5.1, CC-BY-4.0","cost":"400 gp","weight":20,"armorClass":"14 + Dex modifier (max 2)","dexBonus":"Yes, max 2"}'),
    ('Brewer''s Supplies', '/icons/items/_mono/B.svg', '{"name":"Brewer''s Supplies","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"20 gp","weight":9}'),
    ('Bucket', '/icons/items/_mono/B.svg', '{"name":"Bucket","itemType":"Adventuring Gear","rarity":"common","description":"A bucket. Capacity: 3 gallons liquid, 1/2 cubic foot solid.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":2}'),
    ('Burnt othur fumes', '/icons/items/_mono/B.svg', '{"name":"Burnt othur fumes","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 13 Constitution saving throw or take 10 (3d6) poison damage, and must repeat the saving throw at the start of each of its turns. On each successive failed save, the character takes 3 (1d6) poison damage. After three successful saves, the poison ends.\\n\\n**_Inhaled._** These poisons are powders or gases that take effect when inhaled. Blowing the powder or releasing the gas subjects creatures in a 5-foot cube to its effect. The resulting cloud dissipates immediately afterward. Holding one''s breath is ineffective against inhaled poisons, as they affect nasal membranes, tear ducts, and other parts of the body.","source":"SRD 5.1, CC-BY-4.0","cost":"500 gp"}'),
    ('Calligrapher''s supplies', '/icons/items/_mono/C.svg', '{"name":"Calligrapher''s supplies","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":5}'),
    ('Caltrops (bag of 20)', '/icons/items/_mono/C.svg', '{"name":"Caltrops (bag of 20)","itemType":"Adventuring Gear","rarity":"common","description":"As an action, you can spread a bag of caltrops to cover a square area that is 5 feet on a side. Any creature that enters the area must succeed on a DC 15 Dexterity saving throw or stop moving this turn and take 1 piercing damage. Taking this damage reduces the creature''s walking speed by 10 feet until the creature regains at least 1 hit point. A creature moving through the area at half speed doesn''t need to make the save.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":2}'),
    ('Candle', '/icons/items/_mono/C.svg', '{"name":"Candle","itemType":"Adventuring Gear","rarity":"common","description":"For 1 hour, a candle sheds bright light in a 5-foot radius and dim light for an additional 5 feet.","source":"SRD 5.1, CC-BY-4.0","cost":"1 cp"}'),
    ('Canvas', '/icons/items/_mono/C.svg', '{"name":"Canvas","itemType":"Trade Good","rarity":"common","description":"1 sq. yd. of canvas","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":1}'),
    ('Carpenter''s Tools', '/icons/items/_mono/C.svg', '{"name":"Carpenter''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"8 gp","weight":6}'),
    ('Carriage', '/icons/items/_mono/C.svg', '{"name":"Carriage","itemType":"Land Vehicle","rarity":"common","description":"Drawn vehicle.","source":"SRD 5.1, CC-BY-4.0","cost":"100 gp","weight":600}'),
    ('Cart', '/icons/items/_mono/C.svg', '{"name":"Cart","itemType":"Land Vehicle","rarity":"common","description":"Drawn vehicle","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":200}'),
    ('Cartographer''s Tools', '/icons/items/_mono/C.svg', '{"name":"Cartographer''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":6}'),
    ('Case, Crossbow Bolt', '/icons/items/_mono/C.svg', '{"name":"Case, Crossbow Bolt","itemType":"Adventuring Gear","rarity":"common","description":"This wooden case can hold up to twenty crossbow bolts.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":1}'),
    ('Case, Map or Scroll', '/icons/items/_mono/C.svg', '{"name":"Case, Map or Scroll","itemType":"Adventuring Gear","rarity":"common","description":"This cylindrical leather case can hold up to ten rolled-up sheets of paper or five rolled-up sheets of parchment.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":1}'),
    ('Chain (10 feet)', '/icons/items/_mono/C.svg', '{"name":"Chain (10 feet)","itemType":"Adventuring Gear","rarity":"common","description":"A chain has 10 hit points. It can be burst with a successful DC 20 Strength check.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":10}'),
    ('Chain mail', '/icons/items/_mono/C.svg', '{"name":"Chain mail","itemType":"Armor","rarity":"common","description":"Made of interlocking metal rings, chain mail includes a layer of quilted fabric worn underneath the mail to prevent chafing and to cushion the impact of blows. The suit includes gauntlets.","source":"SRD 5.1, CC-BY-4.0","cost":"75 gp","weight":55,"armorClass":"16","dexBonus":"No","stealthDisadvantage":true,"strRequirement":13}'),
    ('Chain shirt', '/icons/items/_mono/C.svg', '{"name":"Chain shirt","itemType":"Armor","rarity":"common","description":"Made of interlocking metal rings, a chain shirt is worn between layers of clothing or leather. This armor offers modest protection to the wearer''s upper body and allows the sound of the rings rubbing against one another to be muffled by outer layers.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":20,"armorClass":"13 + Dex modifier (max 2)","dexBonus":"Yes, max 2"}'),
    ('Chalk (1 piece)', '/icons/items/_mono/C.svg', '{"name":"Chalk (1 piece)","itemType":"Adventuring Gear","rarity":"common","description":"A piece of chalk.","source":"SRD 5.1, CC-BY-4.0","cost":"1 cp"}'),
    ('Chariot', '/icons/items/_mono/C.svg', '{"name":"Chariot","itemType":"Land Vehicle","rarity":"common","description":"Drawn vehicle.","source":"SRD 5.1, CC-BY-4.0","cost":"250 gp","weight":100}'),
    ('Chest', '/icons/items/_mono/C.svg', '{"name":"Chest","itemType":"Adventuring Gear","rarity":"common","description":"A chest. Capacity: 12 cubic feet/300 pounds of gear.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":25}'),
    ('Chicken', '/icons/items/_mono/C.svg', '{"name":"Chicken","itemType":"Trade Good","rarity":"common","description":"One chicken","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp","weight":3}'),
    ('Cinnamon', '/icons/items/_mono/C.svg', '{"name":"Cinnamon","itemType":"Trade Good","rarity":"common","description":"1lb of cinnamon","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":1}'),
    ('Climber''s Kit', '/icons/items/_mono/C.svg', '{"name":"Climber''s Kit","itemType":"Adventuring Gear","rarity":"common","description":"A climber''s kit includes special pitons, boot tips, gloves, and a harness. You can use the climber''s kit as an action to anchor yourself; when you do, you can''t fall more than 25 feet from the point where you anchored yourself, and you can''t climb more than 25 feet away from that point without undoing the anchor.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":12}'),
    ('Clothes, Common', '/icons/items/_mono/C.svg', '{"name":"Clothes, Common","itemType":"Adventuring Gear","rarity":"common","description":"Common clothes.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":3}'),
    ('Clothes, costume', '/icons/items/_mono/C.svg', '{"name":"Clothes, costume","itemType":"Adventuring Gear","rarity":"common","description":"A costume.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":4}'),
    ('Clothes, fine', '/icons/items/_mono/C.svg', '{"name":"Clothes, fine","itemType":"Adventuring Gear","rarity":"common","description":"Fine clothing.","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":6}'),
    ('Clothes, traveler''s', '/icons/items/_mono/C.svg', '{"name":"Clothes, traveler''s","itemType":"Adventuring Gear","rarity":"common","description":"Traveler''s clothing.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":4}'),
    ('Cloves', '/icons/items/_mono/C.svg', '{"name":"Cloves","itemType":"Trade Good","rarity":"common","description":"1lb of cloves.","source":"SRD 5.1, CC-BY-4.0","cost":"3 gp","weight":1}'),
    ('Club', '/icons/items/_mono/C.svg', '{"name":"Club","itemType":"Weapon","rarity":"common","description":"A club","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":2,"damage":"1d4","damageType":"bludgeoning","properties":["Light"]}'),
    ('Cobbler''s Tools', '/icons/items/_mono/C.svg', '{"name":"Cobbler''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":5}'),
    ('Component Pouch', '/icons/items/_mono/C.svg', '{"name":"Component Pouch","itemType":"Adventuring Gear","rarity":"common","description":"A component pouch is a small, watertight leather belt pouch that has compartments to hold all the material components and other special items you need to cast your spells, except for those components that have a specific cost (as indicated in a spell''s description).","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":2}'),
    ('Cook''s utensils', '/icons/items/_mono/C.svg', '{"name":"Cook''s utensils","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":8}'),
    ('Copper', '/icons/items/_mono/C.svg', '{"name":"Copper","itemType":"Trade Good","rarity":"common","description":"1lb of copper.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":1}'),
    ('Copper Piece', '/icons/items/_mono/C.svg', '{"name":"Copper Piece","itemType":"Trade Good","rarity":"common","description":"One silver piece is worth ten copper pieces, which are common among laborers and beggars. A single copper piece buys a candle, a torch, or a piece of chalk.","source":"SRD 5.1, CC-BY-4.0","cost":"1 cp","weight":0.02}'),
    ('Cotton Cloth', '/icons/items/_mono/C.svg', '{"name":"Cotton Cloth","itemType":"Trade Good","rarity":"common","description":"1 sq. yd. of cotton cloth.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":1}'),
    ('Cow', '/icons/items/_mono/C.svg', '{"name":"Cow","itemType":"Trade Good","rarity":"common","description":"One cow.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":1000}'),
    ('Crawler mucus', '/icons/items/_mono/C.svg', '{"name":"Crawler mucus","itemType":"Poison","rarity":"common","description":"This poison must be harvested from a dead or incapacitated crawler. A creature subjected to this poison must succeed on a DC 13 Constitution saving throw or be poisoned for 1 minute. The poisoned creature is paralyzed. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\\n\\n\r\n**_Contact._** Contact poison can be smeared on an object and remains potent until it is touched or washed off. A creature that touches contact poison with exposed skin suffers its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"200 gp"}'),
    ('Crossbow bolt', '/icons/items/_mono/C.svg', '{"name":"Crossbow bolt","itemType":"Ammunition","rarity":"common","description":"Bolts to be used in a crossbow.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":0.08}'),
    ('Crossbow, hand', '/icons/items/_mono/C.svg', '{"name":"Crossbow, hand","itemType":"Weapon","rarity":"common","description":"A hand crossbow.","source":"SRD 5.1, CC-BY-4.0","cost":"75 gp","weight":3,"damage":"1d6","damageType":"piercing","properties":["Ammunition (range 30/120)","Light","Loading"]}'),
    ('Crossbow, heavy', '/icons/items/_mono/C.svg', '{"name":"Crossbow, heavy","itemType":"Weapon","rarity":"common","description":"A heavy crossbow","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":18,"damage":"1d10","damageType":"piercing","properties":["Loading","Two-Handed"]}'),
    ('Crossbow, light', '/icons/items/_mono/C.svg', '{"name":"Crossbow, light","itemType":"Weapon","rarity":"common","description":"A light crossbow.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":5,"damage":"1d8","damageType":"piercing","properties":["Ammunition (range 80/320)","Loading"]}'),
    ('Crowbar', '/icons/items/_mono/C.svg', '{"name":"Crowbar","itemType":"Adventuring Gear","rarity":"common","description":"Using a crowbar grants advantage to Strength checks where the crowbar''s leverage can be applied.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":5}'),
    ('Crystal', '/icons/items/_mono/C.svg', '{"name":"Crystal","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as an arcane focus.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":1}'),
    ('Dagger', '/icons/items/_mono/D.svg', '{"name":"Dagger","itemType":"Weapon","rarity":"common","description":"A dagger.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":1,"damage":"1d4","damageType":"piercing","properties":["Finesse","Light","Thrown (range 20/60)"]}'),
    ('Dart', '/icons/items/_mono/D.svg', '{"name":"Dart","itemType":"Weapon","rarity":"common","description":"A dart.","source":"SRD 5.1, CC-BY-4.0","cost":"5 cp","weight":0.25,"damage":"1d4","damageType":"piercing","properties":["Finesse","Thrown (range 20/60)"]}'),
    ('Dice set', '/icons/items/_mono/D.svg', '{"name":"Dice set","itemType":"Tools","rarity":"common","description":"This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-­‐‑Dragon Ante). A few common examples appear on the Tools table, but other kinds of gaming sets exist. If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set. Each type of gaming set requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp"}'),
    ('Disguise kit', '/icons/items/_mono/D.svg', '{"name":"Disguise kit","itemType":"Tools","rarity":"common","description":"This pouch of cosmetics, hair dye, and small props lets you create disguises that change your physical appearance. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to create a visual disguise.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":3}'),
    ('Drow poison', '/icons/items/_mono/D.svg', '{"name":"Drow poison","itemType":"Poison","rarity":"common","description":"This poison is typically made only by the drow, and only in a place far removed from sunlight. A creature subjected to this poison must succeed on a DC 13 Constitution saving throw or be poisoned for 1 hour. If the saving throw fails by 5 or more, the creature is also unconscious while poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake.\r\n\\n\\n**_Injury._** Injury poison can be applied to weapons, ammunition, trap components, and other objects that deal piercing or slashing damage and remains potent until delivered through a wound or washed off. A creature that takes piercing or slashing damage from an object coated with the poison is exposed to its effects.","source":"SRD 5.1, CC-BY-4.0","cost":"200 gp"}'),
    ('Drum', '/icons/items/_mono/D.svg', '{"name":"Drum","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"6 gp","weight":3}'),
    ('Dulcimer', '/icons/items/_mono/D.svg', '{"name":"Dulcimer","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":10}'),
    ('Electrum Piece', '/icons/items/_mono/E.svg', '{"name":"Electrum Piece","itemType":"Trade Good","rarity":"common","description":"In addition, unusual coins made of other precious metals sometimes appear in treasure hoards. The electrum piece (ep) and the platinum piece (pp) originate from fallen empires and lost kingdoms, and they sometimes arouse suspicion and skepticism when used in transactions. An electrum piece is worth five silver pieces, and a platinum piece is worth ten gold pieces.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":0.02}'),
    ('Emblem', '/icons/items/_mono/E.svg', '{"name":"Emblem","itemType":"Adventuring Gear","rarity":"common","description":"Can be used as a holy symbol.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp"}'),
    ('Essense of either', '/icons/items/_mono/E.svg', '{"name":"Essense of either","itemType":"Poison","rarity":"common","description":"A creature subjected to this poison must succeed on a DC 15 Constitution saving throw or become poisoned for 8 hours. The poisoned creature is unconscious. The creature wakes up if it takes damage or if another creature takes an action to shake it awake.\\n\\n**_Inhaled._** These poisons are powders or gases that take effect when inhaled. Blowing the powder or releasing the gas subjects creatures in a 5-foot cube to its effect. The resulting cloud dissipates immediately afterward. Holding one''s breath is ineffective against inhaled poisons, as they affect nasal membranes, tear ducts, and other parts of the body.","source":"SRD 5.1, CC-BY-4.0","cost":"300 gp"}'),
    ('Fishing Tackle', '/icons/items/_mono/F.svg', '{"name":"Fishing Tackle","itemType":"Adventuring Gear","rarity":"common","description":"This kit includes a wooden rod, silken line, corkwood bobbers, steel hooks, lead sinkers, velvet lures, and narrow netting.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":4}'),
    ('Flail', '/icons/items/_mono/F.svg', '{"name":"Flail","itemType":"Weapon","rarity":"common","description":"A flail.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":2,"damage":"1d8","damageType":"bludgeoning"}'),
    ('Flask or tankard', '/icons/items/_mono/F.svg', '{"name":"Flask or tankard","itemType":"Adventuring Gear","rarity":"common","description":"For drinking. Capacity: 1 pint liquid.","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp","weight":1}'),
    ('Flour', '/icons/items/_mono/F.svg', '{"name":"Flour","itemType":"Trade Good","rarity":"common","description":"1lb of flour","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp","weight":1}'),
    ('Flute', '/icons/items/_mono/F.svg', '{"name":"Flute","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":1}'),
    ('Forgery kit', '/icons/items/_mono/F.svg', '{"name":"Forgery kit","itemType":"Tools","rarity":"common","description":"This small box contains a variety of papers and parchments, pens and inks, seals and sealing wax, gold and silver leaf, and other supplies necessary to create convincing forgeries of physical documents. \\n\\nProficiency with this kit lets you add your proficiency bonus to any ability checks you make to create a physical forgery of a document.","source":"SRD 5.1, CC-BY-4.0","cost":"15 gp","weight":5}'),
    ('Galley', '/icons/items/_mono/G.svg', '{"name":"Galley","itemType":"Waterborne Vehicle","rarity":"common","description":"A waterborne vehicle. Speed 4 mph","source":"SRD 5.1, CC-BY-4.0","cost":"30000 gp"}'),
    ('Ginger', '/icons/items/_mono/G.svg', '{"name":"Ginger","itemType":"Trade Good","rarity":"common","description":"1lb of Ginger.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":1}'),
    ('Glaive', '/icons/items/_mono/G.svg', '{"name":"Glaive","itemType":"Weapon","rarity":"common","description":"A glaive.","source":"SRD 5.1, CC-BY-4.0","cost":"20 gp","weight":6,"damage":"1d10","damageType":"slashing","properties":["Reach","Two-Handed"]}'),
    ('Glassblower''s Tools', '/icons/items/_mono/G.svg', '{"name":"Glassblower''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":5}'),
    ('Goat', '/icons/items/_mono/G.svg', '{"name":"Goat","itemType":"Trade Good","rarity":"common","description":"One goat.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":75}'),
    ('Gold', '/icons/items/_mono/G.svg', '{"name":"Gold","itemType":"Trade Good","rarity":"common","description":"1lb of gold.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","weight":1}'),
    ('Gold Piece', '/icons/items/_mono/G.svg', '{"name":"Gold Piece","itemType":"Trade Good","rarity":"common","description":"With one gold piece, a character can buy a bedroll, 50 feet of good rope, or a goat. A skilled (but not exceptional) artisan can earn one gold piece a day. The gold piece is the standard unit of measure for wealth, even if the coin itself is not commonly used. When merchants discuss deals that involve goods or services worth hundreds or thousands of gold pieces, the transactions don''t usually involve the exchange of individual coins. Rather, the gold piece is a standard measure of value, and the actual exchange is in gold bars, letters of credit, or valuable goods.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":0.02}'),
    ('Grappling hook', '/icons/items/_mono/G.svg', '{"name":"Grappling hook","itemType":"Adventuring Gear","rarity":"common","description":"A grappling hook.","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":4}'),
    ('Greataxe', '/icons/items/_mono/G.svg', '{"name":"Greataxe","itemType":"Weapon","rarity":"common","description":"A greataxe.","source":"SRD 5.1, CC-BY-4.0","cost":"30 gp","weight":7,"damage":"1d12","damageType":"slashing","properties":["Two-Handed"]}'),
    ('Greatclub', '/icons/items/_mono/G.svg', '{"name":"Greatclub","itemType":"Weapon","rarity":"common","description":"A greatclub.","source":"SRD 5.1, CC-BY-4.0","cost":"2 sp","weight":10,"damage":"1d8","damageType":"bludgeoning","properties":["Two-Handed"]}'),
    ('Greatsword', '/icons/items/_mono/G.svg', '{"name":"Greatsword","itemType":"Weapon","rarity":"common","description":"A great sword.","source":"SRD 5.1, CC-BY-4.0","cost":"50 gp","damage":"2d6","damageType":"slashing","properties":["Two-Handed"]}'),
    ('Halberd', '/icons/items/_mono/H.svg', '{"name":"Halberd","itemType":"Weapon","rarity":"common","description":"A halberd.","source":"SRD 5.1, CC-BY-4.0","cost":"20 gp","weight":6,"damage":"1d10","damageType":"slashing","properties":["Reach","Two-Handed"]}'),
    ('Half plate', '/icons/items/_mono/H.svg', '{"name":"Half plate","itemType":"Armor","rarity":"common","description":"Half plate consists of shaped metal plates that cover most of the wearer''s body. It does not include leg protection beyond simple greaves that are attached with leather straps.","source":"SRD 5.1, CC-BY-4.0","cost":"750 gp","weight":40,"armorClass":"15 + Dex modifier (max 2)","dexBonus":"Yes, max 2","stealthDisadvantage":true}'),
    ('Hammer', '/icons/items/_mono/H.svg', '{"name":"Hammer","itemType":"Adventuring Gear","rarity":"common","description":"A hammer.","source":"SRD 5.1, CC-BY-4.0","cost":"1 gp","weight":3}'),
    ('Hammer, sledge', '/icons/items/_mono/H.svg', '{"name":"Hammer, sledge","itemType":"Adventuring Gear","rarity":"common","description":"A sledgehammer","source":"SRD 5.1, CC-BY-4.0","cost":"2 gp","weight":10}'),
    ('Handaxe', '/icons/items/_mono/H.svg', '{"name":"Handaxe","itemType":"Weapon","rarity":"common","description":"A handaxe.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":2,"damage":"1d6","damageType":"slashing","properties":["Light"]}'),
    ('Healer''s Kit', '/icons/items/_mono/H.svg', '{"name":"Healer''s Kit","itemType":"Adventuring Gear","rarity":"common","description":"This kit is a leather pouch containing bandages, salves, and splints. The kit has ten uses. As an action, you can expend one use of the kit to stabilize a creature that has 0 hit points, without needing to make a Wisdom (Medicine) check.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":3}'),
    ('Herbalism Kit', '/icons/items/_mono/H.svg', '{"name":"Herbalism Kit","itemType":"Tools","rarity":"common","description":"This kit contains a variety of instruments such as clippers, mortar and pestle, and pouches and vials used by herbalists to create remedies and potions. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to identify or apply herbs. Also, proficiency with this kit is required to create antitoxin and potions of healing.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":3}'),
    ('Hide Armor', '/icons/items/_mono/H.svg', '{"name":"Hide Armor","itemType":"Armor","rarity":"common","description":"This crude armor consists of thick furs and pelts. It is commonly worn by barbarian tribes, evil humanoids, and other folk who lack access to the tools and materials needed to create better armor.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":12,"armorClass":"12 + Dex modifier (max 2)","dexBonus":"Yes, max 2"}'),
    ('Holy Water (flask)', '/icons/items/_mono/H.svg', '{"name":"Holy Water (flask)","itemType":"Adventuring Gear","rarity":"common","description":"As an action, you can splash the contents of this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact.In either case, make a ranged attack against a target creature, treating the holy water as an improvised weapon. If the target is a fiend or undead, it takes 2d6 radiant damage.\\n\\nA cleric or paladin may create holy water by performing a special ritual. The ritual takes 1 hour to perform, uses 25 gp worth of powdered silver, and requires the caster to expend a 1st-­‐‑level spell slot.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":1}'),
    ('Horn', '/icons/items/_mono/H.svg', '{"name":"Horn","itemType":"Tools","rarity":"common","description":"Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"3 gp","weight":2}'),
    ('Hourglass', '/icons/items/_mono/H.svg', '{"name":"Hourglass","itemType":"Adventuring Gear","rarity":"common","description":"An hourglass.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":1}'),
    ('Hunting Trap', '/icons/items/_mono/H.svg', '{"name":"Hunting Trap","itemType":"Adventuring Gear","rarity":"common","description":"When you use your action to set it, this trap forms a saw-­‐‑toothed steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground. A creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 piercing damage and stop moving. Thereafter, until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet long). A creature can use its action to make a DC 13 Strength check, freeing itself or another creature within its reach on a success. Each failed check deals 1 piercing damage to the trapped creature.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":25}'),
    ('Ink (1 ounce bottle)', '/icons/items/_mono/I.svg', '{"name":"Ink (1 ounce bottle)","itemType":"Adventuring Gear","rarity":"common","description":"A bottle of ink.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp"}'),
    ('Ink pen', '/icons/items/_mono/I.svg', '{"name":"Ink pen","itemType":"Adventuring Gear","rarity":"common","description":"A pen for writing with ink.","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp"}'),
    ('Iron', '/icons/items/_mono/I.svg', '{"name":"Iron","itemType":"Trade Good","rarity":"common","description":"1lb of iron.","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":1}'),
    ('Javelin', '/icons/items/_mono/J.svg', '{"name":"Javelin","itemType":"Weapon","rarity":"common","description":"A javelin","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":2,"damage":"1d6","damageType":"piercing","properties":["Thrown (range 30/120)"]}'),
    ('Jeweler''s Tools', '/icons/items/_mono/J.svg', '{"name":"Jeweler''s Tools","itemType":"Tools","rarity":"common","description":"These special tools include the items needed to pursue a craft or trade.\\n\\n\r\nProficiency with a set of artisan’s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan’s tools requires a separate proficiency.","source":"SRD 5.1, CC-BY-4.0","cost":"25 gp","weight":2}'),
    ('Jug or pitcher', '/icons/items/_mono/J.svg', '{"name":"Jug or pitcher","itemType":"Adventuring Gear","rarity":"common","description":"For drinking a lot. Capacity: 1 gallon liquid.","source":"SRD 5.1, CC-BY-4.0","cost":"2 cp","weight":4}'),
    ('Keelboat', '/icons/items/_mono/K.svg', '{"name":"Keelboat","itemType":"Waterborne Vehicle","rarity":"common","description":"Waterborne vehicle. Speed is 1mph.","source":"SRD 5.1, CC-BY-4.0","cost":"3000 gp"}'),
    ('Ladder (10-foot)', '/icons/items/_mono/L.svg', '{"name":"Ladder (10-foot)","itemType":"Adventuring Gear","rarity":"common","description":"A 10 foot ladder.","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":25}'),
    ('Lamp', '/icons/items/_mono/L.svg', '{"name":"Lamp","itemType":"Adventuring Gear","rarity":"common","description":"A lamp casts bright light in a 15-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.","source":"SRD 5.1, CC-BY-4.0","cost":"5 sp","weight":1}'),
    ('Lamp oil (flask)', '/icons/items/_mono/L.svg', '{"name":"Lamp oil (flask)","itemType":"Adventuring Gear","rarity":"common","description":"Oil usually comes in a clay flask that holds 1 pint. As an action, you can splash the oil in this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. Make a ranged attack against a target creature or object, treating the oil as an improvised weapon. On a hit, the target is covered in oil. If the target takes any fire damage before the oil dries (after 1 minute), the target takes an additional 5 fire damage from the burning oil. You can also pour a flask of oil on the ground to cover a 5-­foot‑square area, provided that the surface is level. If lit, the oil burns for 2 rounds and deals 5 fire damage to any creature that enters the area or ends its turn in the area. A creature can take this damage only once per turn.","source":"SRD 5.1, CC-BY-4.0","cost":"1 sp","weight":1}'),
    ('Lance', '/icons/items/_mono/L.svg', '{"name":"Lance","itemType":"Weapon","rarity":"common","description":"A lance.\r\n\r\nYou have disadvantage when you use a lance to attack a target within 5 feet of you. Also, a lance requires two hands to wield when you aren''t mounted.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":6,"damage":"1d12","damageType":"piercing","properties":["Special (Lance)","Reach"]}'),
    ('Lantern, Bullseye', '/icons/items/_mono/L.svg', '{"name":"Lantern, Bullseye","itemType":"Adventuring Gear","rarity":"common","description":"A bullseye lantern casts bright light in a 60-­‐‑foot cone and dim light for an additional 60 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":2}'),
    ('Lantern, Hooded', '/icons/items/_mono/L.svg', '{"name":"Lantern, Hooded","itemType":"Adventuring Gear","rarity":"common","description":"A hooded lantern casts bright light in a 30-­‐‑foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil. As an action, you can lower the hood, reducing the light to dim light in a 5-­‐‑foot radius.","source":"SRD 5.1, CC-BY-4.0","cost":"5 gp","weight":2}'),
    ('Leather Armor', '/icons/items/_mono/L.svg', '{"name":"Leather Armor","itemType":"Armor","rarity":"common","description":"The breastplate and shoulder protectors of this armor are made of leather that has been stiffened by being boiled in oil. The rest of the armor is made of softer and more flexible materials.","source":"SRD 5.1, CC-BY-4.0","cost":"10 gp","weight":10,"armorClass":"11 + Dex modifier","dexBonus":"Yes"}')
  ) as v(name, image_url, item)
  where not exists (
    select 1 from public.token_assets t
    where t.owner_id = me and t.token_type = 'item' and t.name = v.name
  );
end $$;
